typedef float rational_t;

float __fsqrt( float value );
void fast_sin_cos_approx( float rads, float* sinx, float* cosx );

const rational_t SMALL_ANGLE = 0.00001f;

class vector3d
{
public:
  rational_t x, y, z;

  inline vector3d( const vector3d& v )
  {
    x = v.x;
    y = v.y;
    z = v.z;
  }

  inline vector3d& operator *= ( rational_t d )
  {
    x *= d;
    y *= d;
    z *= d;
    return *this;
  }

  inline rational_t length() const
  {
    return (rational_t)__fsqrt( x*x + y*y + z*z );
  }
};

class vector4d
{
public:
  rational_t x, y, z, w;
};

class matrix4x4
{
public:
  vector4d x, y, z, w;
};

class po
{
private:
  matrix4x4 m;

public:
  void set_rot( const vector3d& rot_dir );
};

#define __fabs(f) __builtin_fabsf(f)

void po::set_rot( const vector3d& rot_dir )
{
  vector3d       v      = rot_dir;
  rational_t     rads   = v.length();
  rational_t     fCos, fSin;
  fast_sin_cos_approx( rads, &fSin, &fCos );

  if (__fabs(rads)>SMALL_ANGLE)
    v *= 1/rads;

  rational_t _1_minus_fCos = ( 1.0f - fCos );

  m.x.x = ( v.x * v.x ) * _1_minus_fCos + fCos;
  m.x.y = ( v.x * v.y ) * _1_minus_fCos - (v.z * fSin);
  m.x.z = ( v.x * v.z ) * _1_minus_fCos + (v.y * fSin);

  m.y.x = ( v.y * v.x ) * _1_minus_fCos + (v.z * fSin);
  m.y.y = ( v.y * v.y ) * _1_minus_fCos + fCos ;
  m.y.z = ( v.y * v.z ) * _1_minus_fCos - (v.x * fSin);

  m.z.x = ( v.z * v.x ) * _1_minus_fCos - (v.y * fSin);
  m.z.y = ( v.z * v.y ) * _1_minus_fCos + (v.x * fSin);
  m.z.z = ( v.z * v.z ) * _1_minus_fCos + fCos;

  m.x.w = m.y.w = m.z.w = 0.0f;
  m.w.x = m.w.y = m.w.z = 0.0f;
  m.w.w = 1.0f;
}
